from datetime import datetime


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}
        self._next_id = 1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime, note: str = "") -> int:
        if start < now:
            raise ValueError("Cannot book an appointment in the past")
        if end <= start:
            raise ValueError("End must be after start")

        if not self.is_free(doctor, start, end):
            raise ValueError("Doctor is not free during this time")

        for appt in self._appointments.values():
            if appt["patient"] == patient and not appt["cancelled"] and appt["start"] >= now:
                raise ValueError("Patient already has an upcoming appointment")

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False,
            "note": note,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        appt = self._appointments.get(appointment_id)
        if appt is None:
            raise ValueError("Unknown appointment id")
        if appt["cancelled"]:
            return
        if (appt["start"] - now).total_seconds() < 24 * 3600:
            # Too late to cancel: keep slot blocked
            return
        appt["cancelled"] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appt in self._appointments.values():
            if appt["doctor"] != doctor or appt["cancelled"]:
                continue
            if start < appt["end"] and appt["start"] < end:
                return False
        return True

    def appointments_of(self, doctor: str) -> list[dict]:
        result = [
            {
                "id": appt_id,
                "patient": appt["patient"],
                "start": appt["start"],
                "end": appt["end"],
            }
            for appt_id, appt in self._appointments.items()
            if appt["doctor"] == doctor and not appt["cancelled"]
        ]
        result.sort(key=lambda a: a["start"])
        return result

    def note(self, appointment_id: int) -> str:
        appt = self._appointments.get(appointment_id)
        if appt is None:
            raise ValueError("Unknown appointment id")
        return appt["note"]
